               <th class=\"text-right\">{{ t('worktime', 'Woche') }}</th>\n                        <th class=\"text-right\">{{ t('worktime', 'Urlaub') }}</th>\n                        <th class=\"actions-col\">{{ t('worktime', 'Aktionen') }}</th>\n                    </tr>\n                </thead>\n                <tbody>\n                    <tr v-for=\"schedule in schedules\" :key=\"schedule.id\">\n                        <td>{{ formatDate(schedule.validFrom) }}</td>\n                        <td class=\"text-right\">{{ schedule.monHours }}</td>\n                        <td class=\"text-right\">{{ schedule.tueHours }}</td>\n                        <td class=\"text-right\">{{ schedule.wedHours }}</td>\n                        <td class=\"text-right\">{{ schedule.thuHours }}</td>\n                        <td class=\"text-right\">{{ schedule.friHours }}</td>\n                        <td class=\"text-right\">{{ schedule.satHours }}</td>\n                        <td class=\"text-right\">{{ schedule.sunHours }}</td>\n                        <td class=\"text-right\"><strong>{{ schedule.weeklyHours }}</strong></td>\n                        <td class=\"text-right\">{{ schedule.vacationDays }}</td>\n                        <td class=\"actions-col\">\n                            <NcButton type=\"tertiary\"\n                                :aria-label=\"t('worktime', 'Bearbeiten')\"\n                                @click=\"startEdit(schedule)\">\n                                <template #icon>\n                                    <Pencil :size=\"20\" />\n                                </template>\n                            </NcButton>\n                            <NcButton v-if=\"schedules.length > 1\"\n                                type=\"tertiary\"\n                                :aria-label=\"t('worktime', 'Löschen')\"\n                                @click=\"confirmDelete(schedule)\">\n                                <template #icon>\n                                    <Close :size=\"20\" />\n                                </template>\n                            </NcButton>\n                        </td>\n                    </tr>\n                </tbody>\n            </table>\n\n            <div v-if=\"!showForm\" class=\"add-button\">\n                <NcButton type=\"secondary\" @click=\"startCreate\">\n                    <template #icon>\n                        <Plus :size=\"20\" />\n                    </template>\n                    {{ t('worktime', 'Neues Profil') }}\n                </NcButton>\n            </div>\n\n            <div v-if=\"showForm\" class=\"schedule-form\">\n                <h5>{{ editingSchedule ? t('worktime', 'Profil bearbeiten') : t('worktime', 'Neues Profil anlegen') }}</h5>\n\n                <div v-if=\"!editingSchedule\" class=\"form-group\">\n                    <label>{{ t('worktime', 'Gültig ab') }} *</label>\n                    <NcDateTimePicker v-model=\"form.validFrom\"\n                        type=\"date\"\n                        :format=\"'DD.MM.YYYY'\"\n                        :disabled-date=\"disablePastDates\" />\n                </div>\n\n                <div class=\"day-hours-row\">\n                    <div v-for=\"day in weekdays\" :key=\"day.key\" class=\"day-input\">\n                        <label>{{ day.label }}</label>\n                        <input v-model.number=\"form.dayHours[day.key]\"\n                            type=\"number\"\n                            min=\"0\"\n                            :max=\"maxDailyHours\"\n                            step=\"0.5\"\n                            :class=\"['input-field', 'input-small', { 'input-error': form.dayHours[day.key] > maxDailyHours }]\">\n                    </div>\n                </div>\n                <p class=\"hint\">{{ t('worktime', 'Max. {hours} Std./Tag', { hours: maxDailyHours }) }}</p>\n\n                <div class=\"form-row\">\n                    <div class=\"form-group\">\n                        <label>{{ t('worktime', 'Wochenstunden (berechnet)') }}</label>\n                        <input :value=\"calculatedWeeklyHours\"\n                            type=\"text\"\n                            class=\"input-field input-small\"\n                            disabled>\n                    </div>\n                    <div class=\"form-group\">\n                        <label>{{ t('worktime', 'Urlaubstage') }} <InfoIcon>{{ t('worktime', 'Voller Jahresanspruch bei diesem Arbeitsmuster. Bei unterjährigem Wechsel wird der tatsächliche Jahresanspruch zeitanteilig aus allen Profilen des Jahres berechnet.') }}</InfoIcon> *</label>\n                        <input v-model.number=\"form.vacationDays\"\n                            type=\"number\"\n                            min=\"0\"\n                            max=\"60\"\n                            class=\"input-field input-small\"\n                            @input=\"vacationTouched = true\">\n                        <p v-if=\"!editingSchedule && !vacationTouched\" class=\"hint\">\n                            {{ t('worktime', 'Vorschlag {days} bei {count} Arbeitstagen (30 × Tage ÷ 5) — anpassbar', { days: suggestedVacationDays, count: workingDaysInForm }) }}\n                        </p>\n                    </div>\n                </div>\n\n                <div class=\"form-actions\">\n                    <NcButton type=\"tertiary\" @click=\"cancelForm\">\n                        {{ t('worktime', 'Abbrechen') }}\n                    </NcButton>\n                    <NcButton type=\"primary\" :disabled=\"!isFormValid\" @click=\"saveForm\">\n                        {{ t('worktime', 'Speichern') }}\n                    </NcButton>\n                </div>\n            </div>\n        </div>\n\n        <NcDialog v-if=\"showDeleteDialog\"\n            :name=\"t('worktime', 'Profil löschen?')\"\n            @close=\"showDeleteDialog = false\">\n            <p>{{ t('worktime', 'Möchten Sie dieses Arbeitszeitprofil wirklich löschen?') }}</p>\n            <template #actions>\n                <NcButton type=\"tertiary\" @click=\"showDeleteDialog = false\">\n                    {{ t('worktime', 'Abbrechen') }}\n                </NcButton>\n                <NcButton type=\"error\" @click=\"deleteConfirmed\">\n                    {{ t('worktime', 'Löschen') }}\n                </NcButton>\n            </template>\n        </NcDialog>\n    </div>\n</template>\n\n<script>\nimport NcButton from '@nextcloud/vue/dist/Components/NcButton.js'\nimport NcDateTimePicker from '@nextcloud/vue/dist/Components/NcDateTimePicker.js'\nimport NcDialog from '@nextcloud/vue/dist/Components/NcDialog.js'\nimport NcLoadingIcon from '@nextcloud/vue/dist/Components/NcLoadingIcon.js'\nimport Pencil from 'vue-material-design-icons/Pencil.vue'\nimport Close from 'vue-material-design-icons/Close.vue'\nimport Plus from 'vue-material-design-icons/Plus.vue'\nimport InfoIcon from './InfoIcon.vue'\nimport { mapGetters, mapActions } from 'vuex'\nimport { showError, showWarning } from '@nextcloud/dialogs'\nimport { formatDateISO, getLocale } from '../utils/dateUtils.js'\nimport SettingsService from '../services/SettingsService.js'\n\nexport default {\n    name: 'WorkScheduleEditor',\n    components: {\n        NcButton,\n        NcDateTimePicker,\n        NcDialog,\n        NcLoadingIcon,\n        Pencil,\n        Close,\n        Plus,\n        InfoIcon,\n    },\n    props: {\n        employeeId: {\n            type: Number,\n            required: true,\n        },\n        // #453: earliest selectable valid-from date (employee entry date, ISO\n        // 'YYYY-MM-DD'). Null means no lower bound in the picker; the backend\n        // still rejects dates inside an already-approved period.\n        entryDate: {\n            type: String,\n            default: null,\n        },\n    },\n    data() {\n        return {\n            showForm: false,\n            editingSchedule: null,\n            showDeleteDialog: false,\n            scheduleToDelete: null,\n            maxDailyHours: 10,\n            // #571 (D5): once the user edits the vacation field, stop auto-\n            // suggesting from the day pattern. Only ever suggests on a new profile.\n            vacationTouched: false,\n            form: this.getEmptyForm(),\n            weekdays: [\n                { key: 'mon', label: this.t('worktime', 'Mo') },\n                { key: 'tue', label: this.t('worktime', 'Di') },\n                { key: 'wed', label: this.t('worktime', 'Mi') },\n                { key: 'thu', label: this.t('worktime', 'Do') },\n                { key: 'fri', label: this.t('worktime', 'Fr') },\n                { key: 'sat', label: this.t('worktime', 'Sa') },\n                { key: 'sun', label: this.t('worktime', 'So') },\n            ],\n        }\n    },\n    computed: {\n        ...mapGetters('workSchedules', ['schedules', 'loading']),\n        calculatedWeeklyHours() {\n            const h = this.form.dayHours\n            return (h.mon + h.tue + h.wed + h.thu + h.fri + (h.sat || 0) + (h.sun || 0)).toFixed(1)\n        },\n        // #571 (D5): number of days with >0 hours in the current form.\n        workingDaysInForm() {\n            return Object.values(this.form.dayHours).filter(v => v > 0).length\n        },\n        // #571 (D5): pro-rated full-year entitlement suggestion for this pattern,\n        // relative to a 5-day full-time base of 30 days (§ 5-style rounding).\n        suggestedVacationDays() {\n            return Math.round(30 * this.workingDaysInForm / 5)\n        },\n        minValidFrom() {\n            // #453: allow back-dating down to the employee's entry date. Without\n            // an entry date there is no lower bound in the picker.\n            if (!this.entryDate) return null\n            const d = new Date(this.entryDate + 'T00:00:00')\n            d.setHours(0, 0, 0, 0)\n            return d\n        },\n        isFormValid() {\n            const h = this.form.dayHours\n            const total = h.mon + h.tue + h.wed + h.thu + h.fri + h.sat + h.sun\n            const allWithinLimit = Object.values(h).every(v => v >= 0 && v <= this.maxDailyHours)\n            return total >= 0\n                && allWithinLimit\n                && this.form.vacationDays >= 0\n                && (this.editingSchedule || this.form.validFrom)\n        },\n    },\n    watch: {\n        employeeId: {\n            immediate: true,\n            async handler(id) {\n                if (id) {\n                    this.fetchSchedules(id)\n                    try {\n                        const val = await SettingsService.get('max_daily_hours')\n                        if (val) {\n                            this.maxDailyHours = parseFloat(val)\n                        }\n                    } catch (e) {\n                        // Fallback bleibt bei 10\n                    }\n                }\n            },\n        },\n        // #571 (D5): on a NEW profile, keep the vacation value in step with the\n        // day pattern until the user overrides it. Never touches an existing\n        // profile's value, never overrides a manual entry.\n        'form.dayHours': {\n            deep: true,\n            handler() {\n                if (!this.editingSchedule && !this.vacationTouched) {\n                    this.form.vacationDays = this.suggestedVacationDays\n                }\n            },\n        },\n    },\n    methods: {\n        ...mapActions('workSchedules', ['fetchSchedules', 'createSchedule', 'updateSchedule', 'deleteSchedule']),\n        getEmptyForm() {\n            return {\n                validFrom: new Date(),\n                dayHours: { mon: 8, tue: 8, wed: 8, thu: 8, fri: 8, sat: 0, sun: 0 },\n                vacationDays: 30,\n            }\n        },\n        disablePastDates(date) {\n            if (!this.minValidFrom) return false\n            return date < this.minValidFrom\n        },\n        formatDate(dateStr) {\n            if (!dateStr) return '-'\n            const d = new Date(dateStr + 'T00:00:00')\n            return d.toLocaleDateString(getLocale())\n        },\n        startCreate() {\n            this.editingSchedule = null\n            this.vacationTouched = false\n            this.form = this.getEmptyForm()\n            this.showForm = true\n        },\n        startEdit(schedule) {\n            this.editingSchedule = schedule\n            this.vacationTouched = true // never auto-change an existing profile (#571 D5)\n            this.form = {\n                validFrom: null,\n                dayHours: {\n                    mon: schedule.monHours,\n                    tue: schedule.tueHours,\n                    wed: schedule.wedHours,\n                    thu: schedule.thuHours,\n                    fri: schedule.friHours,\n                    sat: schedule.satHours || 0,\n                    sun: schedule.sunHours || 0,\n                },\n                vacationDays: schedule.vacationDays,\n            }\n            this.showForm = true\n        },\n        cancelForm() {\n            this.showForm = false\n            this.editingSchedule = null\n        },\n        async saveForm() {\n            try {\n                const data = {\n                    dayHours: this.form.dayHours,\n                    vacationDays: this.form.vacationDays,\n                }\n\n                let result\n                if (this.editingSchedule) {\n                    result = await this.updateSchedule({\n                        employeeId: this.employeeId,\n                        id: this.editingSchedule.id,\n                        data,\n                    })\n                } else {\n                    data.validFrom = this.form.validFrom\n                        ? formatDateISO(this.form.validFrom)\n                        : formatDateISO(new Date())\n                    result = await this.createSchedule({\n                        employeeId: this.employeeId,\n                        data,\n                    })\n                }\n\n                this.showForm = false\n                this.editingSchedule = null\n                this.$emit('updated')\n                this.warnOnQuotaOverage(result?.quotaWarnings)\n            } catch (error) {\n                console.error('Failed to save schedule:', error)\n                const data = error?.response?.data\n                let msg = t('worktime', 'Fehler beim Speichern des Profils')\n                if (data?.errors) {\n                    msg = Object.values(data.errors).flat().join(', ')\n                } else if (data?.message) {\n                    msg = data.message\n                }\n                showError(msg)\n            }\n        },\n        confirmDelete(schedule) {\n            this.scheduleToDelete = schedule\n            this.showDeleteDialog = true\n        },\n        async deleteConfirmed() {\n            try {\n                const result = await this.deleteSchedule({\n                    employeeId: this.employeeId,\n                    id: this.scheduleToDelete.id,\n                })\n                this.$emit('updated')\n                this.warnOnQuotaOverage(result?.quotaWarnings)\n            } catch (error) {\n                console.error('Failed to delete schedule:', error)\n                showError(t('worktime', 'Fehler beim Löschen des Profils'))\n            } finally {\n                this.showDeleteDialog = false\n                this.scheduleToDelete = null\n            }\n        },\n        // #724: a profile change can raise future vacation deductions and push a\n        // year over its quota. The change itself is not blocked (admin action) —\n        // the affected years are surfaced as a non-blocking warning instead.\n        warnOnQuotaOverage(quotaWarnings) {\n            if (!Array.isArray(quotaWarnings) || quotaWarnings.length === 0) {\n                return\n            }\n            quotaWarnings.forEach((w) => {\n                showWarning(t(\n                    'worktime',\n                    'Achtung: Durch die Profiländerung überschreitet der Urlaub {year} das Kontingent um {days} Tage. Bitte die geplanten Urlaube dieses Mitarbeiters prüfen.',\n                    { year: w.year, days: Number(w.over).toLocaleString(getLocale()) },\n                ))\n            })\n        },\n    },\n}\n</script>\n\n<style scoped>\n.work-schedule-editor {\n    margin-top: 16px;\n    padding-top: 16px;\n    border-top: 1px solid var(--color-border);\n}\n\n.work-schedule-editor h4 {\n    margin: 0 0 12px 0;\n    font-size: 1em;\n}\n\n.schedules-table {\n    width: 100%;\n    border-collapse: collapse;\n    margin-bottom: 12px;\n    font-size: 0.9em;\n}\n\n.schedules-table th,\n.schedules-table td {\n    padding: 8px 10px;\n    text-align: left;\n    border-bottom: 1px solid var(--color-border);\n}\n\n.schedules-table th {\n    font-weight: 600;\n    color: var(--color-text-maxcontrast);\n    font-size: 0.9em;\n    border-bottom: 2px solid var(--color-border-dark, var(--color-border));\n}\n\n.text-right {\n    text-align: right;\n}\n\nth.actions-col {\n    width: 5.5rem;\n    text-align: center;\n}\n\ntd.actions-col {\n    display: flex;\n    justify-content: center;\n    gap: 2px;\n}\n\n.add-button {\n    margin-top: 8px;\n}\n\n.schedule-form {\n    background: var(--color-background-dark);\n    padding: 16px;\n    border-radius: var(--border-radius);\n    margin-top: 12px;\n}\n\n.schedule-form h5 {\n    margin: 0 0 12px 0;\n}\n\n.day-hours-row {\n    display: flex;\n    gap: 6px;\n    margin-bottom: 16px;\n}\n\n.day-input {\n    display: flex;\n    flex-direction: column;\n    align-items: center;\n}\n\n.day-input label {\n    display: block;\n    margin-bottom: 4px;\n    font-weight: 500;\n    font-size: 0.9em;\n    text-align: center;\n}\n\n.form-group {\n    margin-bottom: 16px;\n}\n\n.form-group label {\n    display: block;\n    margin-bottom: 4px;\n    font-weight: 500;\n}\n\n.form-row {\n    display: flex;\n    gap: 16px;\n}\n\n.form-row .form-group {\n    flex: 1;\n}\n\n.input-field {\n    width: 100%;\n    padding: 8px;\n    border: 1px solid var(--color-border);\n    border-radius: var(--border-radius);\n    background: var(--color-main-background);\n    color: var(--color-main-text);\n    text-align: center;\n}\n\n.input-small {\n    width: 3.5rem;\n}\n\n.hint {\n    margin: -8px 0 12px 0;\n    font-size: 0.8em;\n    color: var(--color-text-maxcontrast);\n}\n\n.input-error {\n    border-color: var(--color-error, #dc2626) !important;\n    background-color: var(--color-error-element-light, #fef2f2) !important;\n}\n\n.form-actions {\n    display: flex;\n    justify-content: flex-end;\n    gap: 8px;\n    margin-top: 16px;\n}\n</style>\n"],"sourceRoot":""}]);
