ult {\n    name: 'DepartmentForm',\n    components: {\n        NcButton,\n        NcCheckboxRadioSwitch,\n    },\n    props: {\n        department: {\n            type: Object,\n            default: null,\n        },\n    },\n    data() {\n        return {\n            form: {\n                name: '',\n                isActive: true,\n            },\n        }\n    },\n    computed: {\n        isEdit() {\n            return !!this.department\n        },\n        isValid() {\n            return this.form.name.trim().length > 0\n        },\n    },\n    watch: {\n        department: {\n            immediate: true,\n            handler(department) {\n                if (department) {\n                    this.form = {\n                        name: department.name || '',\n                        isActive: department.isActive ?? true,\n                    }\n                } else {\n                    this.form = { name: '', isActive: true }\n                }\n            },\n        },\n    },\n    methods: {\n        ...mapActions('departments', ['createDepartment', 'updateDepartment']),\n        cancel() {\n            this.$emit('cancel')\n        },\n        async save() {\n            try {\n                const data = {\n                    name: this.form.name.trim(),\n                    isActive: this.form.isActive,\n                }\n\n                if (this.isEdit) {\n                    await this.updateDepartment({ id: this.department.id, data })\n                    showSuccessMessage(this.t('worktime', 'Abteilung aktualisiert'))\n                } else {\n                    await this.createDepartment(data)\n                    showSuccessMessage(this.t('worktime', 'Abteilung erstellt'))\n                }\n\n                this.$emit('saved')\n            } catch (error) {\n                showErrorMessage(error.message || this.t('worktime', 'Fehler beim Speichern'))\n            }\n        },\n    },\n}\n</script>\n\n<style scoped>\n.department-form {\n    padding: 20px;\n}\n\n.department-form-header {\n    display: flex;\n    align-items: center;\n    justify-content: space-between;\n    gap: 16px;\n    margin-bottom: 4px;\n}\n\n.department-form-header h3 {\n    margin: 0;\n}\n\n.header-hint {\n    margin: 0 0 20px;\n    font-size: 0.85em;\n    color: var(--color-text-maxcontrast);\n}\n\n.form-group {\n    margin-bottom: 16px;\n}\n\n.form-group label {\n    display: block;\n    margin-bottom: 4px;\n    font-weight: 500;\n}\n\n.input-field {\n    width: 100%;\n    padding: 8px;\n    border: 1px solid var(--color-border);\n    border-radius: var(--border-radius);\n    background: var(--color-main-background);\n    color: var(--color-main-text);\n}\n\n.form-actions {\n    display: flex;\n    justify-content: flex-end;\n    gap: 8px;\n    margin-top: 16px;\n}\n</style>\n"],"sourceRoot":""}]);
